BEGIN;
ON CONFLICT (food_id, coalesce(food_option_id, 0), sort_order) DO UPDATE SET label = EXCLUDED.label, servings = EXCLUDED.servings,
  package_grams = EXCLUDED.package_grams, package_price = EXCLUDED.package_price, product_id = EXCLUDED.product_id,
  description = EXCLUDED.description, package_size = EXCLUDED.package_size, source = EXCLUDED.source;
DELETE FROM public.food_package p USING (VALUES (3,1), (4,2), (5,2), (6,2), (7,1), (8,3), (12,2), (13,2), (14,1), (15,1), (16,1), (21,2), (22,1), (23,1), (25,2), (26,2), (27,2), (28,1), (30,1), (32,2), (36,3), (39,2), (42,3), (43,2), (44,1), (45,1), (52,2), (58,2), (61,1), (65,1), (68,2), (69,1), (70,2), (71,2), (72,3), (73,3), (74,1), (75,3), (76,1), (77,2), (78,2), (80,3), (81,3), (82,2), (83,3), (85,1), (86,1), (87,3), (88,1), (89,1), (90,2), (91,1), (93,3), (94,1), (95,3), (96,1), (97,2), (98,3), (99,3), (100,2), (104,3), (105,1), (106,2), (109,3), (113,1), (114,2), (115,2), (116,1), (118,3)) AS n(food_id, kept)
WHERE p.food_id = n.food_id AND p.food_option_id IS NULL AND p.sort_order >= n.kept
  AND NOT EXISTS (SELECT 1 FROM public.shopping_list_item s WHERE s.food_package_id = p.food_package_id)
  AND NOT EXISTS (SELECT 1 FROM public.pantry_item i WHERE i.food_package_id = p.food_package_id);
COMMIT;
select count(*) from public.food_package where food_option_id is null;